import unittest

from solucao import esta


class TestEstaNoTexto(unittest.TestCase):
    def test_pedaco_esta_no_meio(self):
        """esta devolve True quando o pedaco esta no meio do texto"""
        self.assertEqual(esta("banana", "na"), True)

    def test_pedaco_do_comeco_tambem_esta(self):
        """esta devolve True quando o pedaco esta no comeco do texto"""
        self.assertEqual(esta("banana", "ban"), True)

    def test_pedaco_fora_devolve_false(self):
        """esta devolve False quando o pedaco nao esta no texto"""
        self.assertEqual(esta("banana", "xz"), False)

    def test_pedaco_espalhado_devolve_false(self):
        """esta devolve False quando as letras nao aparecem em ordem"""
        self.assertEqual(esta("banana", "bn"), False)
